const __pageData = JSON.parse('{"title":"The White House","description":"","frontmatter":{"title":"The White House","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["white-house","chain-of-command","benghazi"],"sources":["raw/a-dereliction-of-duty.md","raw/badlands-brief-143.md","raw/badlands-brief-05f.md","raw/badlands-brief-169.md","raw/badlands-brief-559.md","raw/badlands-brief-6f4.md","raw/badlands-brief-6f0.md","raw/badlands-brief-708.md","raw/badlands-brief-b56.md","raw/badlands-brief-f62.md","raw/badlands-brief-fa4.md","raw/badlands-news-brief-017.md","raw/badlands-news-brief-066.md","raw/badlands-news-brief-0ad.md","raw/badlands-news-brief-155.md","raw/badlands-news-brief-1cc.md","raw/badlands-news-brief-201.md","raw/badlands-news-brief-28e.md","raw/badlands-news-brief-362.md","raw/badlands-news-brief-42e.md","raw/badlands-news-brief-471.md","raw/badlands-news-brief-491.md","raw/badlands-news-brief-4b3.md","raw/badlands-news-brief-6e6.md","raw/badlands-news-brief-669.md","raw/badlands-news-brief-71f.md","raw/badlands-news-brief-762.md","raw/badlands-news-brief-860.md","raw/badlands-news-brief-899.md","raw/badlands-news-brief-8d8.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/white-house.md","filePath":"entities/white-house.md","lastUpdated":null}');
